window.NPC_CHUNK_190 = [{"name":"Hetamon Haace","cr":4,"xp":1200,"race":"demon-spawn Tiefling","gender":"Male","age_category":"Adult","classes":[{"class":"cleric of Milani","level":5}],"alignment":"CG","size":"Medium","type":"outsider","sub_types":["native"],"init":1,"senses":["darkvision 60 ft."],"ac":15,"ac_touch":11,"ac_flat_footed":14,"ac_mods":"+3 armor, +1 Dex, +1 shield","hp":26,"hd":"5d8","hd_value":5,"fort":4,"ref":2,"will":7,"resists":["cold 5","electricity 5","fire 5"],"speed":[{"type":"land","speed":30}],"melee":"+1 morningstar +4 (1d8+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel positive energy","details":"6/day, DC 15, 3d6"}],"spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"shatter"}]},{"frequency":"6/day","spells":[{"spell":"rebuke death","details":"1d4+2"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":5,"spellsprepared_concentration":8,"spellsprepared":[{"spell_level":3,"spell_slots":3,"spells":[{"spell":"blindness/deafness"},{"spell":"remove curse","type":"domain"},{"spell":"speak with dead"}]},{"spell_level":2,"spell_slots":4,"spells":[{"spell":"aid"},{"spell":"enthrall"},{"spell":"remove paralysis","type":"domain"},{"spell":"spiritual weapon"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"bless"},{"spell":"cure light wounds","type":"domain"},{"spell":"protection from evil"},{"spell":"sanctuary"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"guidance"},{"spell":"mending"},{"spell":"read magic"}]}],"spelldomains":"Healing, Liberation","strength":10,"dexterity":13,"constitution":10,"intelligence":10,"wisdom":16,"charisma":16,"baseatk":3,"cmb":3,"cmd":15,"feats":[{"feat":"Brew Potion"},{"feat":"Craft Wondrous Item"},{"feat":"Extra Channel"}],"skills":[{"skill":"Bluff","value":8},{"skill":"Diplomacy","value":7},{"skill":"Disguise","value":8},{"skill":"Knowledge (local)","value":2},{"skill":"Knowledge (religion)","value":5},{"skill":"Perception","value":5}],"languages":["Common","Halfling","Infernal"],"sq":["liberation (5 rounds/day)"],"gear":"mwk studded leather, buckler, +1 morningstar, wooden holy symbol of Milani, 111 gp, scroll of align weapon, scroll of lesser restoration, scroll of remove disease, scroll of remove fear, scroll of resist energy","during_combat":"Hetamon casts sanctuary at the start of combat, following with shield of faith. He then focuses his actions on providing healing or assistance to allies. On his own, or when forced to fight, the Tiefling starts a battle with spiritual weapon, then uses blindness/ deafness on the most dangerous-looking foe. Of course, he much prefers to end combats before they begin, often with the aid of an enthrall spell.","morale":"Hetamon is no coward, but neither does he seek to martyr himself. If reduced to fewer than 10 hit points, he attempts to flee combat, go into hiding, and recover. If he's forced to abandon allies, he turns all of his resources to rescuing any who were captured, or if they were killed, avenging their deaths.","source":"AP 98, Pathfinder Player Companion: Blood of Fiends 20"},{"name":"Octavio Sabinus","cr":7,"xp":3200,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":5},{"class":"Hellknight","level":3}],"alignment":"LG","size":"Medium","type":"humanoid","sub_types":["human"],"init":-1,"ac":19,"ac_touch":9,"ac_flat_footed":19,"ac_mods":"+10 armor, -1 Dex","hp":72,"hd":"8d10+24","hd_value":8,"fort":10,"ref":2,"will":6,"save_mods":"Will: +9 vs. fear","defensive_abilities":["bravery +1","force of will"],"speed":[{"type":"land","speed":20,"special":"30 ft. without armor"}],"melee":"+1 halberd +14 (1d10+8/19-20/x3) or mwk mithral short sword +12 (1d6+3/19-20)","ranged":"mwk composite longbow +8 (1d8+3/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"smite chaos"},{"type":"weapon training","details":"polearms +1"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":10,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect chaos"}]},{"frequency":"1/day","spells":[{"spell":"seek the taken","details":"enlarged locate creature"}]},{"frequency":"5/day","spells":[{"spell":"discern lies"}]}],"strength":16,"dexterity":8,"constitution":16,"intelligence":10,"wisdom":12,"charisma":14,"baseatk":8,"cmb":11,"cmd":20,"feats":[{"feat":"Alertness"},{"feat":"Improved Critical (halberd)"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (halberd)"},{"feat":"Weapon Specialization (halberd)"}],"skills":[{"skill":"Acrobatics","value":-4,"special":"-4 when jumping"},{"skill":"Intimidate","value":10},{"skill":"Knowledge (local)","value":5},{"skill":"Knowledge (planes)","value":2},{"skill":"Perception","value":12},{"skill":"Sense Motive","value":12},{"skill":"Survival","value":12}],"languages":["Common"],"sq":["armor training 1","aura of law","discipline (seek the taken)","Hellknight armor 1","Order of the Torrent"],"special_abilities":[{"type":"Aura of Law","kind":"Ex","details":"Octavio's aura of law is equal to his total character level (8th level). Discipline Octavio's seek the taken discipline is detailed on the following page under the Order of the Torrent entry."},{"type":"Force of Will","kind":"Ex","details":"Octavio gains a +2 bonus on Will saves against spells with the fear descriptor."},{"type":"Hellknight Armor","kind":"Ex","details":"When Octavio wears Hellknight plate, he reduces its armor check penalty by 1, increases the maximum Dexterity bonus allowed by 1, and moves at full speed."},{"type":"Smite Chaos","kind":"Su","details":"This ability functions as the paladin's smite evil class feature, but against chaotic-aligned creatures. This ability is twice as effective against outsiders with the chaotic subtype, chaotic-aligned aberrations, and fey."}],"gear":"+1 Hellknight plate, +1 halberd, mwk composite longbow (+3 Str), mithral short sword, cloak of resistance +1, 79 pp, +1 merciful arrows (8)","during_combat":"Octavio prefers to attack chaotic targets at the start of a fight, using smite chaos from the beginning of the battle and focusing on one foe at a time. He prefers to capture enemies alive unless they're mindless creatures, undead, or evil or chaotic outsiders. In battle, he uses Vital Strike on his first attack, then Power Attack with his full attacks. He saves his merciful arrows to use against foes he knows he wants to interrogate later, or to pacify those he suspects are being forced to act against their will.","morale":"Octavio fights to the death if any allies still stand, but on his own he retreats from combat if reduced to fewer than 20 hit points.","source":"AP 98, Pathfinder Campaign Setting: The Inner Sea World Guide 278"},{"name":"Nerrenn Aeelamna","cr":6,"xp":2400,"race":"aquatic elf","gender":"Male","age_category":"Adult","classes":[{"class":"ranger","level":7,"archetype":"shapeshifter"}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["aquatic","elf","shapechanger"],"init":4,"senses":["low-light vision"],"ac":19,"ac_touch":12,"ac_flat_footed":17,"ac_mods":"+5 armor, +2 Dex, +2 natural","hp":71,"hd":"7d10+28","hd_value":7,"fort":5,"ref":5,"will":4,"save_mods":"+2 vs. enchantment","immunities":["sleep"],"weaknesses":["sickened"],"speed":[{"type":"land","speed":40},{"type":"swim","speed":30}],"melee":"2 claws +9 (1d4+7)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"combat style","details":"natural weapon"},{"type":"favored enemy","details":"monstrous humanoids +4, humans +2"}],"spellsprepared_caster":"ranger","spellsprepared_caster_level":4,"spellsprepared_concentration":4,"spellsprepared":[{"spell_level":2,"spell_slots":1,"spells":[{"spell":"bear's endurance"}]},{"spell_level":1,"spell_slots":2,"spells":[{"spell":"charm animal"},{"spell":"longstrider"}]}],"strength":16,"dexterity":14,"constitution":15,"intelligence":10,"wisdom":14,"charisma":10,"baseatk":7,"cmb":8,"cmd":22,"feats":[{"feat":"Aspect of the Beast"},{"feat":"Endurance"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Climb","value":10},{"skill":"Handle Animal","value":8},{"skill":"Intimidate","value":5},{"skill":"Knowledge (geography)","value":4},{"skill":"Perception","value":12},{"skill":"Stealth","value":9},{"skill":"Swim","value":18}],"languages":["Common","Elven"],"sq":["amphibious","elven magic","hunter's bond (shark animal companion named Sesskeress)","shifter's blessing (form of the dragon)","track +3","wild empathy +5","woodland stride"],"gear":"+1 chain shirt, vest of the deep, scrimshaw-handled fish-gutting knife worth 200 gp, belt made of skum skin set with walrus-tusk eyes and clasped with a copper buckle worth 125 gp, potion of cure moderate wounds (2)","before_combat":"Before confronting the PCs, Nerrenn casts bear's endurance and longstrider on himself, and then uses his shifter's blessing to activate his form of the dragon.","during_combat":"If the PCs have any animal companions, Nerrenn uses charm animal on the first round of battle to prevent one such companion from attacking him. He attacks with his claws, focusing attacks on humans if possible, and uses Power Attack at all times (these bonuses and penalties are included in his melee attacks above).","morale":"If reduced to fewer than 30 hit points, Nerrenn flees by racing to the ocean and swimming out to join his master's side in the Drowned Eye. If confronted there, Nerrenn fights to the death.","source":"AP 99, Pathfinder Campaign Setting: Inner Sea Races 242, Pathfinder RPG Advanced Player's Guide 126"},{"name":"Sesskeress","xp":0,"race":"Shark","age_category":"Adult","classes":[{"class":"animal companion","level":4}],"alignment":"N","size":"Medium","type":"animal","sub_types":["aquatic"],"init":6,"senses":["blindsense 30 ft.","low-light vision","scent"],"ac":19,"ac_touch":12,"ac_flat_footed":17,"ac_mods":"+2 Dex, +7 natural","hp":34,"hd":"4d8+16","hd_value":4,"fort":8,"ref":6,"will":2,"defensive_abilities":["evasion"],"speed":[{"type":"swim","speed":60}],"melee":"bite +7 (1d6+6)","space":"5 ft.","reach":"5 ft.","strength":18,"dexterity":14,"constitution":18,"intelligence":1,"wisdom":12,"charisma":2,"baseatk":3,"cmb":7,"cmd":19,"feats":[{"feat":"Improved Initiative"},{"feat":"Improved Natural Armor"}],"skills":[{"skill":"Perception","value":7},{"skill":"Swim","value":16}],"during_combat":"Sesskeress remains in the Acisazi harbor and can't aid his master in a fight on land, but accompanies the ranger out to the Drowned Eye and fights loyally at his side thereafter.","morale":"Sesskeress fights to the death.","source":"AP 99"},{"name":"Zombie Shark","cr":7,"xp":3200,"race":"Great white shark","age_category":"Adult","alignment":"NE","size":"Huge","type":"undead","sub_types":["aquatic"],"templates_applied":"@zombie","init":1,"senses":["darkvision 60 ft."],"ac":22,"ac_touch":9,"ac_flat_footed":21,"ac_mods":"+1 Dex, +13 natural, -2 size","hp":65,"hd":"9d8+9","hd_value":9,"fort":3,"ref":4,"will":6,"dr":"5/slashing","immunities":["undead traits"],"speed":[{"type":"swim","speed":60}],"melee":"bite +12 (2d8+8)","space":"15 ft.","reach":"10 ft.","strength":27,"dexterity":13,"wisdom":10,"charisma":10,"baseatk":6,"cmb":16,"cmd":27,"cmd_special":"can't be tripped","feats":[{"feat":"Toughness"}],"skills":[{"skill":"Swim","value":16}],"sq":["staggered"],"during_combat":"The zombie shark attacks the closest foe each round, and pursues for up to 1 mile from the Drowned Eye before returning here to patrol.","morale":"The zombie shark fights until destroyed.","source":"AP 99, Pathfinder RPG Bestiary 4 241, Pathfinder RPG Bestiary 288"},{"name":"Menotheguro","cr":8,"xp":4800,"race":"Aboleth","age_category":"Adult","classes":[{"class":"necromancer","level":3}],"alignment":"LE","size":"Huge","type":"aberration","sub_types":["aquatic"],"init":7,"senses":["darkvision 60 ft."],"auras":["mucus cloud (5 ft., DC 19)"],"ac":23,"ac_touch":12,"ac_flat_footed":20,"ac_mods":"+1 deflection, +3 Dex, +11 natural, -2 size","hp":112,"hd":"8d8+3d6+66","hd_value":11,"fort":8,"ref":8,"will":13,"speed":[{"type":"land","speed":10},{"type":"swim","speed":60}],"melee":"4 tentacles +13 (1d6+7 plus slime)","space":"15 ft.","reach":"15 ft.","spell_like_abilities_caster_level":16,"spell_like_abilities_concentration":19,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"hypnotic pattern"},{"spell":"illusory wall"},{"spell":"mirage arcana"},{"spell":"persistent image"},{"spell":"programmed image"},{"spell":"project image"},{"spell":"veil"}]},{"frequency":"3/day","spells":[{"spell":"dominate monster"}]},{"frequency":"7/day","spells":[{"spell":"grave touch","details":"1 round"}]}],"spellsprepared_caster":"necromancer","spellsprepared_caster_level":3,"spellsprepared_concentration":7,"spellsprepared":[{"spell_level":2,"spell_slots":3,"spells":[{"spell":"command undead"},{"spell":"false life"},{"spell":"invisibility"}]},{"spell_level":1,"spell_slots":4,"spells":[{"spell":"chill touch"},{"spell":"magic missile","count":2},{"spell":"ray of enfeeblement"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"prestidigitation"},{"spell":"read magic"}]}],"prohibited_schools":"conjuration, transmutation","strength":24,"dexterity":16,"constitution":20,"intelligence":18,"wisdom":18,"charisma":16,"baseatk":7,"cmb":16,"cmd":30,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Casting"},{"feat":"Command Undead"},{"feat":"Craft Wondrous Item"},{"feat":"Eschew Materials"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Scribe Scroll"},{"feat":"Weapon Focus (tentacle)"}],"skills":[{"skill":"Bluff","value":14},{"skill":"Knowledge (arcana)","value":18},{"skill":"Knowledge (geography)","value":15},{"skill":"Knowledge (history)","value":15},{"skill":"Knowledge (religion)","value":18},{"skill":"Perception","value":18},{"skill":"Spellcraft","value":18},{"skill":"Swim","value":29}],"languages":["Common","Aboleth","Aklo","Azlanti","Elven","Infernal"],"sq":["arcane bond (ring of protection +1)","power over undead"],"gear":"pale blue rhomboid ioun stone, ring of protection +1 (worn on the tip of a tentacle), spellbook (strips of preserved seaweed inscribed with runes containing all prepared spells)","before_combat":"Menotheguro casts false life on itself before entering combat.","during_combat":"The aboleth would prefer to capture PCs alive, since it can then kill them at its leisure and use the interaction of their souls with the Drowned Eye's necromantic energies to further fuel its work. If it manages to dominate a foe, it prefers to command the foe to simply lay down arms rather than risk her escaping control by forcing her to attack her allies.","morale":"Menotheguro isn't interested in risking its life for its project. If reduced to fewer than 50 hit points, it casts invisibility and attempts to flee. The monster swims as quickly as it can out to sea to seek depths where it is more comfortable, and if the PCs allow it to escape, it doesn't return to antagonize Acisazi.","source":"AP 99, Pathfinder RPG Bestiary 8"},{"name":"Manticce Kaleekii","cr":18,"xp":153600,"race":"devil-spawn Tiefling","gender":"Female","age_category":"Adult","classes":[{"class":"aristocrat","level":2},{"class":"witch","level":17}],"alignment":"CN","size":"Medium","type":"outsider","sub_types":["native"],"init":2,"senses":["darkvision 60 ft."],"ac":25,"ac_touch":17,"ac_flat_footed":22,"ac_mods":"+4 armor, +4 deflection, +2 Dex, +1 dodge, +4 natural","hp":160,"hd":"2d8+17d6+89","hd_value":19,"fort":9,"ref":7,"will":16,"resists":["cold 5","electricity 5","fire 5"],"speed":[{"type":"land","speed":30}],"melee":"+2 mithral dagger +11 (1d4+2/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"hexes","details":"agony, charm, disguise, evil eye, major healing, retribution, tongues, vision, ward"}],"spell_like_abilities_caster_level":19,"spell_like_abilities_concentration":21,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"pyrotechnics"}]}],"spellsprepared_caster":"witch","spellsprepared_caster_level":17,"spellsprepared_concentration":22,"spellsprepared":[{"spell_level":9,"spell_slots":1,"spells":[{"spell":"dominate monster"}]},{"spell_level":8,"spell_slots":2,"spells":[{"spell":"demand"},{"spell":"mass charm monster"}]},{"spell_level":7,"spell_slots":3,"spells":[{"spell":"harm"},{"spell":"heal"},{"spell":"quickened lightning bolt"}]},{"spell_level":6,"spell_slots":4,"spells":[{"spell":"flesh to stone"},{"spell":"greater dispel magic"},{"spell":"quickened false life"},{"spell":"stone to flesh"}]},{"spell_level":5,"spell_slots":5,"spells":[{"spell":"baleful polymorph"},{"spell":"dominate person"},{"spell":"quickened cure light wounds","count":2},{"spell":"teleport"}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"charm monster"},{"spell":"dimension door","count":2},{"spell":"scrying"},{"spell":"vermin shape II"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"dispel magic"},{"spell":"fly"},{"spell":"major image"},{"spell":"suggestion"},{"spell":"vampiric touch"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"alter self"},{"spell":"blindness/deafness","count":2},{"spell":"mirror image"},{"spell":"web"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"charm person"},{"spell":"cure light wounds","count":3},{"spell":"ray of enfeeblement"},{"spell":"reduce person"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"arcane mark"},{"spell":"detect magic"},{"spell":"light"},{"spell":"message"}]}],"patron":"trickery","strength":10,"dexterity":14,"constitution":14,"intelligence":20,"wisdom":12,"charisma":14,"baseatk":9,"cmb":9,"cmd":36,"feats":[{"feat":"Brew Potion"},{"feat":"Combat Casting"},{"feat":"Craft Wand"},{"feat":"Craft Wondrous Item"},{"feat":"Defensive Combat Training"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Iron Will"},{"feat":"Quicken Spell"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":16},{"skill":"Diplomacy","value":26},{"skill":"Intimidate","value":16},{"skill":"Knowledge (arcana)","value":18},{"skill":"Knowledge (local)","value":13},{"skill":"Knowledge (nobility)","value":13},{"skill":"Perception","value":23},{"skill":"Sense Motive","value":25},{"skill":"Spellcraft","value":27},{"skill":"Use Magic Device","value":24}],"languages":["Common","Azlanti","Elven","Gnome","Halfling","Infernal","Varisian"],"sq":["witch's familiar (scarlet spider named Gozzlemer)"],"gear":"+2 mithral dagger, amulet of natural armor +4, corset of dire witchcraft, headband of mental superiority +2, ring of protection +4, numerous other valuables spread around Cobweb Manor, wand of charm monster (20 charges), wand of cure serious wounds (44 charges), wand of lightning bolt (CL 10th, 31 charges)","during_combat":"Manticce casts quickened false life and mirror image on the first round of combat, then a quickened lightning bolt and mass charm monster on the second. She favors dominate monster and dominate person after that, hoping to make allies out of enemies. If she dominates the whole party, she sends them back to Kintargo to continue their lives but periodically steps in to maintain her domination; how this plays out over the long term is left to you, but Manticce is no friend of Thrune, so it may be that being dominated by the witch has no real effect on the campaign.","morale":"If reduced below 80 hit points, Manticce teleports to safety elsewhere in her home. The PCs soon thereafter find themselves relentlessly attacked by various dominated minions and allies, along with repeated demand spells, until they can track down Manticce and either defeat her or apologize; how they might accomplish this may well lead to a series of adventures of your own design.","source":"AP 99, Pathfinder Player Companion: Blood of Fiends 21, Pathfinder RPG Bestiary 264, Pathfinder RPG Advanced Player's Guide 65"},{"name":"Menador Soldier","cr":2,"xp":600,"race":"human","age_category":"Adult","classes":[{"class":"fighter","level":3}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":3,"ac":19,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+6 armor, +3 Dex","hp":30,"hd":"3d10+9","hd_value":3,"fort":5,"ref":4,"will":2,"save_mods":"Will: +1 vs. fear","defensive_abilities":["bravery +1"],"speed":[{"type":"land","speed":20}],"melee":"mwk halberd +5 (1d10+1/x3)","ranged":"mwk heavy crossbow +3 (1d10+2/19-20)","space":"5 ft.","reach":"5 ft.","strength":12,"dexterity":17,"constitution":14,"intelligence":10,"wisdom":13,"charisma":8,"baseatk":3,"cmb":4,"cmd":17,"feats":[{"feat":"Deadly Aim"},{"feat":"Exotic Weapon Proficiency (heavy ballista)"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Weapon Focus (heavy crossbow)"}],"skills":[{"skill":"Intimidate","value":5},{"skill":"Perception","value":4},{"skill":"Sense Motive","value":4}],"languages":["Common"],"sq":["armor training 1"],"gear":"mwk chainmail, mwk halberd, mwk heavy crossbow with 10 bolts and 3 screaming bolts, 40 gp","during_combat":"On the first round of combat, a soldier fires at a foe using a screaming bolt; these shrieking attacks also double as alarms for the keep. Menador soldiers prefer to break into equal-sized groups, with half of their number engaging foes in melee while the others hold back and provide support via their crossbows. They always use Deadly Aim with crossbow attacks, and their ranged attacks reflect this tactic in the above statistics.","morale":"Menador soldiers are loyal to House Thrune, and fight to the death until their leader, Captain Lucian, is obviously defeated. At this point, any remaining Menador soldiers make a fighting retreat to the east in an attempt to flee back to the Chelish heartlands.","source":"AP 99"},{"name":"Lucian Thrune","cr":9,"xp":6400,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"aristocrat","level":3},{"class":"cavalier","level":7}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":-1,"ac":18,"ac_touch":9,"ac_flat_footed":18,"ac_mods":"+9 armor, -1 Dex","hp":103,"hd":"3d8+7d10+47","hd_value":10,"fort":9,"ref":2,"will":6,"speed":[{"type":"land","speed":20}],"melee":"+1 flaming greatsword +13 (2d6+5/17-20 plus 1d6 fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"banner +2"},{"type":"cavalier's charge"},{"type":"challenge","details":"3/day, +7 damage, +2 AC"},{"type":"tactician","details":"2/day, Distracting Charge, 6 rounds"}],"strength":16,"dexterity":8,"constitution":16,"intelligence":10,"wisdom":12,"charisma":14,"baseatk":9,"cmb":12,"cmd":21,"feats":[{"feat":"Duck and Cover"},{"feat":"Improved Critical (greatsword)"},{"feat":"Mounted Combat"},{"feat":"Power Attack"},{"feat":"Ride-By Attack"},{"feat":"Skill Focus (Ride)"},{"feat":"Toughness"},{"feat":"Vital Strike"}],"skills":[{"skill":"Diplomacy","value":15},{"skill":"Handle Animal","value":15},{"skill":"Intimidate","value":15},{"skill":"Perception","value":14},{"skill":"Ride","value":13}],"languages":["Common"],"sq":["expert trainer +3","lion's call","mount (wyvern named Zailosorn)","order of the lion"],"gear":"mwk full plate, +1 flaming greatsword, iron and silver bracelet set with small opals depicting devils being eaten by bloated dolls (worth 700 gp), long dark cloak set with black peacock feathers (worth 100 gp), soft leather scissor case containing scissors depicting a lewdly posed gnome (worth 75 gp), small vanity mirror painted with angels (worth 50 gp), silver-rimmed reading spectacles in an iron case (worth 50 gp), iron key for the trunk in area C21","during_combat":"Lucian prefers to fight astride his wyvern, and uses Ride-By Attack while using Vital Strike with his greatsword. He's conservative with Power Attack, and tends to use that feat only when he can somewhat offset the penalty on his attack rolls with a charge, flanking, or the like. He uses his tactician ability to grant Distracting Charge to allies, particularly to his wyvern when Lucian uses Ride-By Attack. He prefers to challenge obvious worshipers of faiths opposed to Asmodeus, but if given no other option challenges non-Human foes, particularly halflings-Lucian bristles at the mere thought of halflings not being enslaved. When mounted, Lucian must guide his mount with his knees since he uses a two-handed weapon, but unless there are extenuating circumstances, he can't fail this DC 5 Ride check or the DC 10 Ride check to fight with a combat-trained mount.","morale":"Lucian's fear of failure outweighs his sense of self-preservation, but he won't hesitate to break off combat to retreat and recover if outclassed. If reduced to fewer than 30 hit points, he retreats to area C21 to use the healing magic kept there, abandoning his soldiers and even his wyvern if he feels that doing so will help him reach that room. He then commands the devil that guards area C21 to accompany him back to battle. At this point, he fights to the death. If cornered with no option to flee, he prefers to leap from a cliff's edge, hoping to fall to his death rather than allow the PCs to take him alive.","source":"AP 99, Pathfinder RPG Advanced Player's Guide 32"},{"name":"Sentinel Of Torag","cr":6,"xp":2400,"race":"graven guardian","age_category":"Adult","alignment":"N","size":"Medium","type":"construct","templates_applied":"advanced","init":4,"senses":["darkvision 60 ft.","low-light vision"],"ac":26,"ac_touch":14,"ac_flat_footed":22,"ac_mods":"+4 Dex, +12 natural","hp":53,"hd":"6d10+20","hd_value":6,"hp_mods":"fast healing 2","fort":4,"ref":8,"will":7,"dr":"5/adamantine","immunities":["construct traits"],"sr":16,"weaknesses":["faith bound"],"speed":[{"type":"land","speed":40}],"melee":"+1 keen warhammer +12 (1d8+6/19-20/x3), slam +6 (1d6+2)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":2,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"haste","details":"self only"}]}],"strength":20,"dexterity":19,"wisdom":16,"charisma":5,"baseatk":6,"cmb":11,"cmd":25,"skills":[{"skill":"Acrobatics","value":4,"special":"+4 to jump"}],"sq":["guardian domains (Earth, Protection)","magic weapon"],"gear":"warhammer","during_combat":"The sentinels give intruders a round to retreat back down the stairs, but if anyone attacks or attempts to push by to get to the door to area C24, the constructs attack. They don't pursue foes north, but do pursue foes south into area C24 and beyond.","morale":"The sentinels fight until destroyed.","source":"AP 99, Pathfinder RPG Bestiary 3 290, 140"},{"name":"Tayacet Tiora","cr":7,"xp":3200,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"investigator","level":8}],"alignment":"LN","size":"Medium","type":"humanoid","sub_types":["human"],"init":7,"ac":24,"ac_touch":13,"ac_flat_footed":21,"ac_mods":"+4 armor, +3 Dex, +3 natural, +4 shield","hp":63,"hd":"8d8+24","hd_value":8,"fort":4,"ref":9,"will":7,"save_mods":"+6 vs. poison","defensive_abilities":["trap sense +2"],"speed":[{"type":"land","speed":30}],"melee":"+1 rapier +10 (1d6+1/18-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"studied combat","details":"+4, 3 rounds"},{"type":"studied strike","details":"+3d6"}],"extractsprepared_caster":"investigator","extractsprepared_caster_level":8,"extractsprepared":[{"spell_level":3,"spells":[{"spell":"cure serious wounds"},{"spell":"fly"},{"spell":"seek thoughts"}]},{"spell_level":2,"spells":[{"spell":"barkskin"},{"spell":"cure moderate wounds"},{"spell":"invisibility"},{"spell":"perceive cues"},{"spell":"see invisibility"}]},{"spell_level":1,"spells":[{"spell":"comprehend languages"},{"spell":"cure light wounds","count":2},{"spell":"expeditious retreat"},{"spell":"shield"}]}],"strength":10,"dexterity":16,"constitution":14,"intelligence":16,"wisdom":12,"charisma":8,"baseatk":6,"cmb":9,"cmd":19,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Brew Potion"},{"feat":"Combat Expertise"},{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":10},{"skill":"Craft (alchemy)","value":3,"special":"+8 to create alchemical items"},{"skill":"Diplomacy","value":10},{"skill":"Disable Device","value":18},{"skill":"Intimidate","value":10},{"skill":"Knowledge (arcana)","value":10},{"skill":"Knowledge (engineering)","value":8},{"skill":"Knowledge (local)","value":14},{"skill":"Knowledge (nobility)","value":10},{"skill":"Knowledge (religion)","value":8},{"skill":"Linguistics","value":14},{"skill":"Perception","value":17},{"skill":"Sense Motive","value":12},{"skill":"Spellcraft","value":10}],"languages":["Common","Aquan","Dwarven","Elven","Gnome","Halfling","Infernal","Minkaian","Shadowtongue","Strix","Tengu","Tien","Undercommon","Varisian"],"sq":["alchemy (alchemy crafting +8)","inspiration (7/day)","investigator talents (canny observer, extend potion, perceptive tracking)","keen recollection","poison lore","swift alchemy","trapfinding +4"],"gear":"+1 studded leather, +1 rapier, eyes of the eagle, alchemy crafting kit, belt pouch, flint and steel, ink, inkpen, mwk manacles, poisoning sheath, thieves' tools, 55 gp, potion of expeditious retreat, potion of haste, potion of spider climb, blue whinnis (4)","before_combat":"Tayacet drinks extracts of barkskin and shield before any fight.","during_combat":"Tayacet prefers to avoid combat if possible, but if forced to fight, she uses her extracts to maintain superior mobility over her foes. She prefers to take her time in striking blows, and would rather spend a few rounds in hiding setting up a studied strike on an enemy rather than recklessly attacking each round. She seeks a defensive place to hide and heal whenever reduced to fewer than 25 hit points, returning to battle as soon as she's healed as much damage as she can.","morale":"Tayacet flees combat if reduced to fewer than 15 hit points.","source":"AP 99, Pathfinder RPG Advanced Class Guide 30"},{"name":"Nox","cr":9,"xp":6400,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"fighter","level":7,"archetype":"polearm master"}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"templates_applied":"bearded-devil-bound, broken soul","init":0,"senses":["blinders","darkvision 60 ft.","see in darkness"],"ac":26,"ac_touch":10,"ac_flat_footed":26,"ac_mods":"+8 armor, +8 natural","hp":99,"hd":"7d10+56","hd_value":7,"hp_mods":"regeneration 5 (good spells, good weapons)","fort":14,"ref":3,"will":4,"save_mods":"+4 vs. poison","dr":"5/-","resists":["acid 5","cold 5","electricity 5","fire 30","sonic 5"],"weaknesses":["contract bound"],"speed":[{"type":"land","speed":15}],"melee":"+1 vicious glaive +16 (1d10+13/x3 plus 2d6) or torturous touch +13 touch (2d6 plus 1d6 Dexterity damage and convulsions)","ranged":"throwing axe +7 (1d6+6)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"baleful gaze","details":"DC 11"},{"type":"pole fighting"},{"type":"steadfast pike"}],"spell_like_abilities_caster_level":7,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"summon","details":"1 lemure 100%, level 2"}]},{"frequency":"3/day","spells":[{"spell":"dimension door"},{"spell":"rage"}]}],"strength":22,"dexterity":10,"constitution":22,"intelligence":10,"wisdom":12,"charisma":7,"baseatk":7,"cmb":13,"cmd":23,"feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Diehard"},{"feat":"Endurance"},{"feat":"Great Fortitude"},{"feat":"Power Attack"},{"feat":"Stand Still"},{"feat":"Step Up"},{"feat":"Toughness"},{"feat":"Weapon Focus (glaive)"},{"feat":"Weapon Specialization (glaive)"}],"skills":[{"skill":"Climb","value":6},{"skill":"Intimidate","value":15},{"skill":"Knowledge (planes)","value":1},{"skill":"Perception","value":10},{"skill":"Sense Motive","value":9}],"languages":["Common"],"sq":["torturous touch"],"special_abilities":[{"type":"Blinders","kind":"Ex","details":"As long as Nox wears her blinders, she loses limit her vision to no farther than 10 feet; she remains no farther than 10 ft. from Cizmekris at all times as a result. As a standard action, an adjacent creature can yank a chain hanging from the back of the blinders, causing the device to painfully rip away. This deals 2d4 points of damage to Nox, but restores her sight and baleful gaze ability."}],"gear":"+2 chainmail, +1 vicious glaive, throwing axes (4), belt of giant strength +2, cloak of resistance +1, ring of sustenance, blinders, skeleton key","during_combat":"Nox uses her glaive's reach to fight the PCs while they engage in melee with others. She prefers to fight with this weapon, but switches to her torturous touch if forced into close quarters. If Cizmekris removes her blinders, Nox swiftly moves away from her \"master\" to keep him out of reach of her gaze if possible-though she doesn't bother to keep any dottari guards sheltered from the gaze. She doesn't bother summoning a lemure in this battle. She avoids using rage so she can retain the option of using dimension door if needed to pursue the PCs.","morale":"Nox fights to the death.","source":"AP 99, Pathfinder RPG Bestiary 4 56, 24; Pathfinder RPG Advanced Player's Guide 106"},{"name":"Skinsaw Cultist","cr":5,"xp":1600,"race":"human","age_category":"Adult","classes":[{"class":"cleric of Norgorber","level":3},{"class":"rogue","level":3}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":7,"ac":17,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+3 armor, +3 Dex, +1 shield","hp":51,"hd":"6d8+21","hd_value":6,"fort":6,"ref":7,"will":6,"defensive_abilities":["evasion","trap sense +1"],"speed":[{"type":"land","speed":30}],"melee":"+1 war razor +8 (1d4+3/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"3/day, DC 11, 2d6"},{"type":"sneak attack","details":"+2d6"}],"spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"5/day","spells":[{"spell":"bleeding touch","details":"1 round"},{"spell":"copycat","details":"3 rounds"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":3,"spellsprepared_concentration":5,"spellsprepared":[{"spell_level":2,"spell_slots":3,"spells":[{"spell":"cure moderate wounds"},{"spell":"hold person"},{"spell":"invisibility","type":"domain"}]},{"spell_level":1,"spell_slots":4,"spells":[{"spell":"cure light wounds","count":2},{"spell":"disguise self","type":"domain"},{"spell":"divine favor"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"guidance"},{"spell":"light"}]}],"spelldomains":"Death, Trickery","strength":12,"dexterity":16,"constitution":14,"intelligence":8,"wisdom":15,"charisma":10,"baseatk":4,"cmb":5,"cmd":18,"feats":[{"feat":"Craft Wondrous Item"},{"feat":"Improved Initiative"},{"feat":"Martial Weapon Proficiency (war razor)"},{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Disguise","value":9},{"skill":"Knowledge (local)","value":4},{"skill":"Knowledge (religion)","value":4},{"skill":"Perception","value":11},{"skill":"Sleight of Hand","value":8},{"skill":"Stealth","value":12}],"languages":["Common"],"sq":["rogue talent (finesse rogue)","trapfinding +1"],"gear":"mwk studded leather, mwk buckler, +1 war razor","during_combat":"The cultists organize into pairs, so that they outnumber PCs two to one if possible-if they choose to attack the whole party while they are skulking in the off-limits part of the Opera House, all six take part in the fight. If a cultist surprises a PC, he casts hold person to try to end the fight before it begins. The cultists cast divine favor on the first round of combat, then move to flank foes. A cultist reduced to 20 or fewer hit points casts invisibility, then flees to heal as best as she can with her spells before returning to the combat try to finish the fight. These cultists try not to kill the PCs, but rather render them unconscious-hoping to save as many as possible for a ritual sacrifice (likely to take place in area G20) at 1:00 a.m. Captured PCs are held prisoner in area G21 until that time comes.","morale":"A Skinsaw cultist fights to the death.","source":"AP 99"},{"name":"Cizmekris","cr":10,"xp":9600,"race":"polymorphed bone devil","gender":"Male","age_category":"Adult","classes":[{"class":"inquisitor of Asmodeus","level":3}],"alignment":"LE","size":"Medium","type":"outsider","sub_types":["devil","evil","extraplanar","lawful"],"init":13,"ac":17,"ac_touch":17,"ac_flat_footed":12,"ac_mods":"+2 deflection, +5 Dex","hp":123,"hd":"10d10+3d8+55","hd_value":13,"fort":14,"ref":13,"will":10,"speed":[{"type":"fly","speed":60,"maneuverability":"good"},{"type":"land","speed":30}],"melee":"+1 flaming heavy mace +18 (1d6+8 plus 1d6 fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"judgment","details":"1/day"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":18,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"fly"}]},{"frequency":"at-will","spells":[{"spell":"detect alignment"},{"spell":"dimensional anchor"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"invisibility","details":"self only"},{"spell":"major image"},{"spell":"wall of ice"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"1 bone devil 35%, level 4"}]},{"frequency":"3/day","spells":[{"spell":"quickened invisibility","details":"self only"}]},{"frequency":"7/day","spells":[{"spell":"copycat","details":"3 rounds"}]}],"spellsknown_caster":"inquisitor","spellsknown_caster_level":3,"spellsknown_concentration":7,"spellsknown":[{"spell_level":1,"spell_slots":4,"spells":[{"spell":"burst bonds"},{"spell":"command"},{"spell":"divine favor"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"brand"},{"spell":"detect magic"},{"spell":"guidance"},{"spell":"read magic"},{"spell":"resistance"}]}],"spelldomains":"Trickery","strength":21,"dexterity":21,"constitution":18,"intelligence":18,"wisdom":19,"charisma":22,"baseatk":12,"cmb":19,"cmd":34,"feats":[{"feat":"Alertness"},{"feat":"Combat Reflexes"},{"feat":"Deceitful"},{"feat":"Improved Initiative"},{"feat":"Multiattack"},{"feat":"Outflank"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (invisibility)"}],"skills":[{"skill":"Bluff","value":26},{"skill":"Disguise","value":26},{"skill":"Fly","value":31},{"skill":"Intimidate","value":23},{"skill":"Knowledge (planes)","value":13},{"skill":"Knowledge (religion)","value":14},{"skill":"Perception","value":24},{"skill":"Sense Motive","value":25},{"skill":"Spellcraft","value":20},{"skill":"Stealth","value":21},{"skill":"Use Magic Device","value":19}],"languages":["Common","Azlanti","Celestial","Draconic","Infernal"],"sq":["monster lore +4","solo tactics","stern gaze +1","track +1"],"gear":"+1 flaming heavy mace, ring of counterspells (dispel magic), wand of sculpt corpse (19 charges)","before_combat":"Cizmekris attempts to summon a bone devil. If he has the chance, he casts divine favor and shield of faith.","during_combat":"Cizmekris starts combat by casting invisibility on himself in the first round, then uses a major image to make himself appear elsewhere in the area, hoping to draw off enemy resources, wasting them on the illusion. Once battle begins in earnest, he moves into melee with his mace, fighting with allies so he can use his Outflank feat to gain a +4 flanking bonus on his attacks. He always uses Power Attack when flanking a foe. (Since his allies    don't actually have Outflank, the feat allows his allies to take attacks of opportunity when Cizmekris confirms a critical hit, but he can't take attacks of opportunity in response to his allies' critical hits.) Cizmekris relies on walls of ice to block off attackers that use ranged weapons or ranged spells against him so he can focus exclusively on fighting up close. Cizmekris has no method to exit his polymorphed condition himself in this adventure, but if the PCs manage to dispel the effect (the polymorph any object functions at caster level 15th), they face the bone devil in his true form.","morale":"If reduced to 20 hit points or fewer, Cizmekris uses a quickened invisibility to vanish, then retreats into the Kintargo Opera House to heal: the board room (area E8), the archives (area F6), and the vault (area G12) all contain healing supplies, and Cizmekris makes for the closest one. Once he's healed, he searches for surviving allies, preferring to seek out Jilia in her coffin (area H2) in the subbasement, and then returns with Jilia at his side to launch a new attack. Cizmekris has been ordered to remain in the opera house until the PCs are dead, and so the best he can do in a hopeless battle is to hide in the building; if the bone devil can simply outwait the PCs or force them to retreat, his orders allow him to teleport back to the temple of Asmodeus to report to Corinstian Grivenner. Should this occur, you'll need to incorporate the bone devil into the next adventure yourself, as Hell's Rebels assumes he is defeated in \"Dance of the Damned.\"","source":"AP 99, Pathfinder RPG Bestiary 74, Pathfinder RPG Advanced Player's Guide 38"},{"name":"Jilia Bainilus","cr":9,"xp":6400,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"aristocrat","level":9}],"alignment":"CE","size":"Medium","type":"undead","sub_types":["augmented humanoid","human"],"templates_applied":"vampire","init":7,"senses":["darkvision 60 ft."],"ac":25,"ac_touch":14,"ac_flat_footed":21,"ac_mods":"+5 armor, +3 Dex, +1 dodge, +6 natural","hp":121,"hd":"9d8+81","hd_value":9,"hp_mods":"fast healing 5","fort":10,"ref":8,"will":11,"defensive_abilities":["channel resistance +4"],"dr":"10/magic and silver","immunities":["undead traits"],"resists":["cold 10","electricity 10"],"weaknesses":["vampire weaknesses"],"speed":[{"type":"land","speed":30}],"melee":"slam +9 (1d4+3 plus energy drain)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"blood drain"},{"type":"children of the night"},{"type":"create spawn"},{"type":"dominate","details":"DC 21"},{"type":"energy drain","details":"2 levels, DC 21"}],"strength":14,"dexterity":16,"intelligence":16,"wisdom":16,"charisma":24,"baseatk":6,"cmb":8,"cmb_special":"+10 disarm","cmd":22,"cmd_special":"24 vs. disarm","feats":[{"feat":"Alertness"},{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Disarm"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Persuasive"},{"feat":"Skill Focus (Diplomacy)"},{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":27},{"skill":"Diplomacy","value":24},{"skill":"Intimidate","value":21},{"skill":"Knowledge (history)","value":12},{"skill":"Knowledge (local)","value":12},{"skill":"Knowledge (nobility)","value":12},{"skill":"Linguistics","value":15},{"skill":"Perception","value":25},{"skill":"Sense Motive","value":25},{"skill":"Stealth","value":10}],"languages":["Common","Aquan","Celestial","Draconic","Dwarven","Elven","Gnome","Halfling","Infernal","Shadowtongue","Strix","Varisian"],"sq":["change shape (dire bat or wolf, beast shape II)","gaseous form","shadowless","spider climb"],"gear":"+1 glamered chain shirt, headband of alluring charisma +2","during_combat":"Jilia Bainilus is under the control of Aluceda Zhol, the high priest of Zon-Kuthon in Kintargo. As the former lord-mayor's vampiric mistress, Aluceda has forbidden Jilia from certain actions. While she must follow Barzillai Thrune's orders, not even he can countermand Aluceda's directive never to create spawn of her own- Aluceda wants to deny Jilia any measure of power over anything below her. This extends to her dominate ability as well. Anyone Jilia successfully dominates can be used to attack others who immediately threaten her, but if there are no other threats, she's been ordered to send those she's dominated to the Shadowsquare to offer themselves to Aluceda and be placed under her control. Statistics for Aluceda are not presented until the next adventure: any PC who manages to follow these commands may well need to be removed from play until he or she can be rescued by surviving allies. Otherwise, Jilia's first action in combat is to call on several swarms of rats to join the battle. After that, she simply attacks with her slam attacks; once battle is joined, she doesn't bother making dominate attempts.","morale":"If reduced to 0 hit points or fewer, Jilia retreats to her coffin in area H2.","source":"AP 99, Pathfinder RPG Bestiary 270"},{"name":"Jilia Bainilus Human","cr":7,"xp":3200,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"aristocrat","level":9}],"alignment":"CG","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":16,"ac_touch":11,"ac_flat_footed":15,"ac_mods":"+5 armor, +1 Dex","hp":49,"hd":"9d8+9","hd_value":9,"fort":3,"ref":4,"will":10,"speed":[{"type":"land","speed":30}],"melee":"Reprisal +10 (1d6+4) or unarmed strike +7 (1d3-1 nonlethal)","space":"5 ft.","reach":"5 ft.","strength":8,"dexterity":12,"constitution":10,"intelligence":14,"wisdom":14,"charisma":20,"baseatk":6,"cmb":5,"cmb_special":"+7 disarm","cmd":16,"cmd_special":"18 vs. disarm","feats":[{"feat":"Combat Expertise"},{"feat":"Improved Disarm"},{"feat":"Iron Will"},{"feat":"Persuasive"},{"feat":"Skill Focus (Diplomacy)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":14},{"skill":"Diplomacy","value":22},{"skill":"Intimidate","value":16},{"skill":"Knowledge (history)","value":11},{"skill":"Knowledge (local)","value":11},{"skill":"Knowledge (nobility)","value":11},{"skill":"Linguistics","value":14},{"skill":"Perception","value":11},{"skill":"Sense Motive","value":14}],"languages":["Common","Aquan","Celestial","Draconic","Dwarven","Elven","Gnome","Halfling","Infernal","Shadowtongue","Strix","Varisian"],"gear":"+1 glamered chain shirt, headband of alluring charisma +2","during_combat":"Without a weapon, Jilia prefers to flee rather than fight. If she has allies, she takes an aid another action each round to grant a bonus to an ally's AC. If she gains a weapon (she hopes for her heirloom, Reprisal, but otherwise prefers weapons she can use with Weapon Finesse), she fights with a bravery that rivals that of most soldiers, particularly when she fights at the side of allies or against a hated enemy, such as House Thrune.","morale":"With a renewed and obsessive hatred of House Thrune, Jilia fights to the death when facing agents of Barzillai or the church of Asmodeus, yet harbors a deep fear of the undead and of vampires in particular. She flees any combat against an obvious vampire unless the PCs can bolster her courage (how they can do so is left for you to determine-but a successful DC 20 Diplomacy or Intimidate check should do the trick).","source":"AP 99"},{"name":"Molly Mayapple","cr":8,"xp":4800,"race":"halfling","gender":"Female","age_category":"Old","classes":[{"class":"rogue","level":8}],"alignment":"CN","size":"Small","type":"humanoid","sub_types":["halfling","shapechanger"],"templates_applied":"natural wererat","init":2,"senses":["low-light vision","scent"],"ac":19,"ac_touch":15,"ac_flat_footed":16,"ac_mods":"+4 armor, +1 deflection, +2 Dex, +1 dodge, +1 size","hp":47,"hd":"8d8+8","hd_value":8,"fort":4,"ref":9,"will":5,"save_mods":"+2 vs. fear","defensive_abilities":["evasion","improved uncanny dodge","trap sense +2"],"speed":[{"type":"land","speed":15}],"melee":"mwk rapier +10 (1d4-4/18-20)","ranged":"+1 hand crossbow +11 (1d3+1/19-20 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack +4d6 plus 4 bleed"}],"strength":3,"dexterity":14,"constitution":12,"intelligence":14,"wisdom":14,"charisma":16,"baseatk":6,"cmb":1,"cmd":15,"feats":[{"feat":"Deadly Aim"},{"feat":"Dodge"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Rapid Reload"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (hand crossbow)"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Bluff","value":14},{"skill":"Climb","value":6},{"skill":"Diplomacy","value":14},{"skill":"Disable Device","value":12},{"skill":"Disguise","value":14},{"skill":"Knowledge (history)","value":5},{"skill":"Knowledge (local)","value":8},{"skill":"Knowledge (nobility)","value":5},{"skill":"Knowledge (religion)","value":5},{"skill":"Linguistics","value":9},{"skill":"Perception","value":15},{"skill":"Sense Motive","value":13},{"skill":"Stealth","value":14}],"languages":["Common","Abyssal","Elven","Halfling","Infernal","Shadowtongue","Undercommon","Varisian"],"sq":["change shape (Human, hybrid, and dire rat; polymorph)","lycanthropic empathy (rats and dire rats)","rogue talents (bleeding attack +4, combat trick, finesse rogue, weapon training)","trapfinding +4"],"gear":"+1 studded leather, +1 hand crossbow with 10 bolts poisoned with oil of taggit, mwk rapier, ring of protection +1, small gold locket (contains a miniature painting of a smiling halfling child) engraved with the words \"To my beloved niece, fortune in your travels -MG\" worth 250 gp, gold bee broach with central diamond worth 1,000 gp, gold serpentine necklace with blue enamel head and set with a matching grinning devil locket worth 700 gp, gold ring set with black obsidian ravens worth 250 gp, gold earrings designed to resemble rampant owlbears worth 250 gp each.","before_combat":"Molly is unlikely to engage in combat in this adventure, but she still keeps 10 of her hand crossbow bolts prepared with oil of taggit.","during_combat":"Molly has little interest in fighting or revealing her wererat nature yet, and as such she is unlikely to shift forms. If faced with a fight that she can't avoid, however, she assumes her hybrid form-in this shape, her physical body is bolstered by her feral nature.","morale":"If Molly's confronted with violence, she either attempts to flee or begs for mercy, trusting in her appearance as a frail old woman if she thinks that will stay her enemy's hand. If she escapes, she plots revenge.","source":"AP 99, Pathfinder RPG Bestiary 197"},{"name":"Honored Of Kaoling","cr":4,"xp":1200,"race":"Kanabo hobgoblin","age_category":"Adult","classes":[{"class":"samurai","level":4}],"alignment":"LE","size":"Medium","type":"outsider","sub_types":["goblinoid","native"],"init":3,"senses":["darkvision 60 ft."],"ac":19,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+6 armor, +3 Dex","hp":52,"hd":"4d10+24","hd_value":4,"hp_mods":"regeneration 1 (acid and fire)","fort":9,"ref":4,"will":3,"defensive_abilities":["resolve 2/day"],"speed":[{"type":"land","speed":20}],"melee":"mwk naginata +10 (1d8+5/x4)","ranged":"mwk composite longbow +8 (1d8+5/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"challenge","details":"2/day, +4 damage, +2 to Intimidate"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"bull's strength"}]},{"frequency":"3/day","spells":[{"spell":"command"},{"spell":"doom"},{"spell":"magic weapon"}]}],"strength":20,"dexterity":16,"constitution":20,"intelligence":12,"wisdom":15,"charisma":10,"baseatk":4,"cmb":9,"cmd":22,"feats":[{"feat":"Cleave"},{"feat":"Power Attack"}],"skills":[{"skill":"Handle Animal","value":7},{"skill":"Intimidate","value":7},{"skill":"Perception","value":6},{"skill":"Ride","value":7},{"skill":"Stealth","value":4},{"skill":"Survival","value":6}],"languages":["Giant","Goblin","Tien"],"sq":["dark rider (low-light vision and scent when mounted)","mount (yzobu)","mounted archer","order of the eclipse","weapon expertise (naginata)"],"gear":"mwk mountain pattern armor (Pathfinder RPG Ultimate Equipment), mwk composite longbow (+5 Str) with 20 arrows, mwk naginata (Pathfinder RPG Ultimate Equipment), potion of cure serious wounds","before_combat":"The honored of Kaoling depends on his mount to track down foes. If a fight seems likely, he casts bull's strength and magic weapon.","during_combat":"The honored of Kaoling moves to be adjacent to the most powerful foe as soon as possible, preferring to fight in melee without his mount. If this isn't a realistic option, he remains mounted and uses his longbow. If badly injured, the honored of Kaoling seeks to fall back long enough for his regeneration to heal him.","source":"Distant Shores, Pathfinder RPG Ultimate Combat 18"},{"name":"Khazat Karelem","cr":10,"xp":9600,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":11}],"alignment":"LN","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":20,"ac_touch":12,"ac_flat_footed":18,"ac_mods":"+8 armor, +1 Dex, +1 dodge","hp":109,"hd":"11d10+44","hd_value":11,"hp_mods":"(56 points of nonlethal damage)","fort":10,"ref":4,"will":3,"save_mods":"Will: +3 vs. fear","defensive_abilities":["bravery +3"],"speed":[{"type":"land","speed":40}],"melee":"+2 halberd +22 (1d10+13/x3), bite +16 (1d4+7) or dagger of repose +17 (1d4+8/x3), bite +16 (1d4+7)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"weapon training","details":"polearms +2, light blades +1"}],"strength":21,"dexterity":13,"constitution":16,"intelligence":4,"wisdom":6,"charisma":8,"baseatk":11,"cmb":16,"cmb_special":"+20 grapple, +18 sunder","cmd":28,"cmd_special":"30 vs. grapple, 30 vs. sunder","feats":[{"feat":"Combat Reflexes"},{"feat":"Deflect Arrows"},{"feat":"Dodge"},{"feat":"Greater Grapple"},{"feat":"Greater Weapon Focus (halberd)"},{"feat":"Improved Grapple"},{"feat":"Improved Sunder"},{"feat":"Improved Unarmed Strike"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Weapon Focus (halberd)"},{"feat":"Weapon Specialization (halberd)"}],"skills":[{"skill":"Diplomacy","value":6},{"skill":"Intimidate","value":8},{"skill":"Perception","value":4},{"skill":"Sense Motive","value":1}],"languages":["Common"],"sq":["armor training 3"],"gear":"+2 breastplate, +2 halberd, dagger of repose","source":"Feast Of Dust"},{"name":"Pershpia","cr":8,"xp":4800,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"bard","level":8}],"alignment":"NE","size":"Medium","type":"undead","sub_types":["human"],"templates_applied":"dread ghoul","init":3,"senses":["darkvision 60 ft.","scent"],"ac":23,"ac_touch":15,"ac_flat_footed":19,"ac_mods":"+6 armor, +1 deflection, +3 Dex, +1 dodge, +2 natural","hp":87,"hd":"8d8+48","hd_value":8,"fort":7,"ref":9,"will":8,"save_mods":"+4 vs. bardic performance, language-dependent, and sonic","defensive_abilities":["channel resistance +4"],"immunities":["undead traits"],"speed":[{"type":"climb","speed":30},{"type":"land","speed":30}],"melee":"bite +9 (1d6+3 plus paralysis), 2 claws +9 (1d6+3 plus paralysis) or +1 scorpion whip +10 (1d6+4/18-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bardic performance 23 rounds/day","details":"move action; countersong, dirge of doom [DC 19], distraction, fascinate [DC 19], inspire competence +3, inspire courage +2, suggestion [DC 19]"},{"type":"command ghouls"},{"type":"create spawn"},{"type":"paralysis","details":"1d4+1 rounds, DC 14"}],"spellsknown_caster":"bard","spellsknown_caster_level":8,"spellsknown_concentration":13,"spellsknown":[{"spell_level":3,"spell_slots":3,"spells":[{"spell":"charm monster"},{"spell":"haste"},{"spell":"slow"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"fleshy facade"},{"spell":"glitterdust"},{"spell":"invisibility"},{"spell":"suggestion"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"charm person"},{"spell":"expeditious retreat"},{"spell":"grease"},{"spell":"magic aura"},{"spell":"undetectable alignment"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"open/close"},{"spell":"read magic"}]}],"strength":16,"dexterity":16,"intelligence":14,"wisdom":14,"charisma":20,"baseatk":6,"cmb":9,"cmd":24,"feats":[{"feat":"Arcane Strike"},{"feat":"Deceitful"},{"feat":"Dodge"},{"feat":"Mobility"},{"feat":"Spell Focus (enchantment)"}],"skills":[{"skill":"Bluff","value":14},{"skill":"Climb","value":10},{"skill":"Diplomacy","value":12},{"skill":"Disguise","value":14},{"skill":"Knowledge (local)","value":13},{"skill":"Knowledge (planes)","value":13},{"skill":"Perception","value":13},{"skill":"Perform (act)","value":16},{"skill":"Perform (oratory)","value":16},{"skill":"Sense Motive","value":9},{"skill":"Spellcraft","value":13},{"skill":"Stealth","value":13},{"skill":"Survival","value":10},{"skill":"Use Magic Device","value":16}],"languages":["Common","Infernal"],"sq":["bardic knowledge +4","lore master 1/day","versatile performance (act, oratory)"],"special_abilities":[{"type":"Command Ghouls","kind":"Su","details":"As a free action, Pershpia can automatically command all normal ghouls within 30 ft. (as per the command undead spell). Normal ghouls never attack a dread ghoul unless compelled."},{"type":"Create Spawn","kind":"Su","details":"Any creature killed by Pershpia rises the following midnight as a dread ghoul. The new dread ghoul isn't under her control. A protection from evil or gentle repose spell cast on the corpse prevents this."}],"gear":"+2 chain shirt, +1 scorpion whip, ring of protection +1","source":"Feast Of Dust, Advanced Bestiary 86"}];
